import{_ as e,C as i,c as n,o as t,j as r,b as a,a0 as l,a as s,w as u,G as d,a1 as h}from"./chunks/framework.DKRgXLPU.js";const o=JSON.parse('{"title":"Trainingsmethoden","description":"","frontmatter":{},"headers":[],"relativePath":"de/education/training/index.md","filePath":"de/education/training/index.md"}');const g=e({name:"de/education/training/index.md"},[["render",function(e,o,g,c,b,f){const m=i("Mermaid");return t(),n("div",null,[o[2]||(o[2]=r("h1",{id:"trainingsmethoden",tabindex:"-1"},[s("Trainingsmethoden "),r("a",{class:"header-anchor",href:"#trainingsmethoden","aria-label":'Permalink to "Trainingsmethoden"'},"​")],-1)),o[3]||(o[3]=r("p",null,"Wenn deine Technik solide ist, was übst du dann? Hier stagnieren viele Spieler – sie feilen immer weiter an ihrer Technik, obwohl das eigentliche Entwicklungspotenzial woanders liegt.",-1)),o[4]||(o[4]=r("div",{class:"tip custom-block"},[r("p",{class:"custom-block-title"},"Die große Idee"),r("p",null,"Die meisten Spieler stagnieren, weil sie sich immer nur auf die Technik konzentrieren, während das eigentliche Entwicklungspotenzial woanders liegt. Spitzenspieler trainieren Anpassungsfähigkeit, Entscheidungsfindung und mentale Stärke – nicht nur die Technik.")],-1)),(t(),a(h,null,{default:u(()=>[d(m,{id:"mermaid-11",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BTrainingsentwicklung%5D%20--%3E%20B%5BAnf%C3%A4nger%3A%20Technische%20%C3%9Cbungen%5D%0A%20%20%20%20B%20--%3E%20C%5BMittelstufe%3A%20Zuf%C3%A4lliges%20%C3%9Cben%5D%0A%20%20%20%20C%20--%3E%20D%5BFortgeschritten%3A%20Drucksimulation%5D%0A%20%20%20%20D%20--%3E%20E%5BElite%3A%20Mentales%20Training%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20B%20fill%3A%23f5f5f5%0A%20%20%20%20style%20C%20fill%3A%23fff4e1%0A%20%20%20%20style%20D%20fill%3A%23e8f5e9%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A"})]),fallback:u(()=>[...o[0]||(o[0]=[s(" Loading... ",-1)])]),_:1})),o[5]||(o[5]=l('<h2 id="uber-die-technische-wiederholung-hinaus" tabindex="-1">Über die technische Wiederholung hinaus <a class="header-anchor" href="#uber-die-technische-wiederholung-hinaus" aria-label="Permalink to &quot;Über die technische Wiederholung hinaus&quot;">​</a></h2><p>Die meisten Spieler trainieren durch das Wiederholen von Würfen. Das ist wichtig für Anfänger, aber fortgeschrittene Spieler brauchen mehr:</p><table tabindex="0"><thead><tr><th>Schulungsart</th><th>Was es entwickelt</th><th>Wann verwenden?</th></tr></thead><tbody><tr><td>Technische Übungen</td><td>Mechanik, Form</td><td>Neue Fähigkeiten erlernen, Probleme lösen</td></tr><tr><td>Zufällige Übung</td><td>Anpassungsfähigkeit, Entscheidungsfindung</td><td>Wettkampfvorbereitung</td></tr><tr><td>Drucksimulation</td><td>Mentale Stärke</td><td>Vor wichtigen Ereignissen</td></tr><tr><td>Mentales Training</td><td>Fokus, Erholung, Selbstvertrauen</td><td>Andauernd, oft vernachlässigt</td></tr></tbody></table><h2 id="die-trainingspyramide" tabindex="-1">Die Trainingspyramide <a class="header-anchor" href="#die-trainingspyramide" aria-label="Permalink to &quot;Die Trainingspyramide&quot;">​</a></h2>',4)),(t(),a(h,null,{default:u(()=>[d(m,{id:"mermaid-82",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BWettbewerb%5D%20--%3E%20B%5BSpielsimulation%5D%0A%20%20%20%20B%20--%3E%20C%5BDrucktraining%5D%0A%20%20%20%20C%20--%3E%20D%5BZuf%C3%A4lliges%2FVariiertes%20Training%5D%0A%20%20%20%20D%20--%3E%20E%5BBlockierte%20technische%20Praxis%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23fff4e1%0A%20%20%20%20style%20B%20fill%3A%23e8f5e9%0A%20%20%20%20style%20C%20fill%3A%23e3f2fd%0A%20%20%20%20style%20D%20fill%3A%23f5f5f5%0A%20%20%20%20style%20E%20fill%3A%23f5f5f5%0A"})]),fallback:u(()=>[...o[1]||(o[1]=[s(" Loading... ",-1)])]),_:1})),o[6]||(o[6]=l('<div class="warning custom-block"><p class="custom-block-title">Häufiger Fehler</p><p><strong>Die meisten Spieler verbringen zu viel Zeit im unteren Bereich.</strong> Elite-Spieler arbeiten auf allen Ebenen der Pyramide, wobei der Schwerpunkt beim Aufstieg auf den oberen Ebenen liegt.</p></div><h2 id="blockiertes-vs-zufalliges-training" tabindex="-1">Blockiertes vs. zufälliges Training <a class="header-anchor" href="#blockiertes-vs-zufalliges-training" aria-label="Permalink to &quot;Blockiertes vs. zufälliges Training&quot;">​</a></h2><h3 id="blockierte-ubung" tabindex="-1">Blockierte Übung <a class="header-anchor" href="#blockierte-ubung" aria-label="Permalink to &quot;Blockierte Übung&quot;">​</a></h3><p>Den gleichen Wurf mehrmals wiederholen:</p><ul><li>20 Punkte aus 7 Metern</li><li>20 Schüsse auf dasselbe Ziel</li><li>Gleiche Distanz, gleicher Wurf</li></ul><p><strong>Gut geeignet für:</strong> Erste Lernschritte, Aufbau von Selbstvertrauen, Aufwärmen <strong>Einschränkung:</strong> Lässt sich nicht gut auf Wettbewerbe übertragen.</p><h3 id="zufallige-ubung" tabindex="-1">Zufällige Übung <a class="header-anchor" href="#zufallige-ubung" aria-label="Permalink to &quot;Zufällige Übung&quot;">​</a></h3><p>Variiere alles:</p><ul><li>Unterschiedliche Wurfdistanzen.</li><li>Abwechselnd zielen und schießen</li><li>Die Ziele ändern sich ständig.</li></ul><p><strong>Gut geeignet für:</strong> Wettkampfvorbereitung, Aufbau von Anpassungsfähigkeit <strong>Fühlt sich an:</strong> Schwieriger, mehr Fehler, weniger &quot;produktiv&quot; <strong>Realität:</strong> Bessere langfristige Kundenbindung und Transferleistung</p><h3 id="die-forschung" tabindex="-1">Die Forschung <a class="header-anchor" href="#die-forschung" aria-label="Permalink to &quot;Die Forschung&quot;">​</a></h3><p>Studien zeigen übereinstimmend:</p><ul><li>Blockiertes Üben fühlt sich besser an (schnelle Verbesserung sichtbar)</li><li>Zufälliges Üben führt zu besseren Wettkampfleistungen</li><li>Der „Kampf“ des zufälligen Übens ist der Ort, an dem Lernen stattfindet.</li></ul><h2 id="drucksimulation" tabindex="-1">Drucksimulation <a class="header-anchor" href="#drucksimulation" aria-label="Permalink to &quot;Drucksimulation&quot;">​</a></h2><p>Man kann dem Druck im Wettkampf nicht standhalten, wenn man ihn im Training nie erlebt hat.</p><h3 id="ubungsdruck-erzeugen" tabindex="-1">Übungsdruck erzeugen <a class="header-anchor" href="#ubungsdruck-erzeugen" aria-label="Permalink to &quot;Übungsdruck erzeugen&quot;">​</a></h3><p><strong>Folgen:</strong></p><ul><li>Liegestütze für Fehlversuche</li><li>Der Verlierer kauft Kaffee</li><li>Punkte zählen für etwas</li></ul><p><strong>Szenarien:</strong></p><ul><li>Situationen, die man unbedingt schaffen muss</li><li>Wir liegen mit 12:10 zurück und müssen punkten.</li><li>Letzte Boule des Spiels</li></ul><p><strong>Publikum:</strong></p><ul><li>Übung mit Menschenbeobachtung</li><li>Nimm dich selbst auf Video auf</li><li>Kündige an, was du vorhast</li></ul><p><strong>Ermüdung:</strong></p><ul><li>Üben, wenn man müde ist</li><li>Ende der langen Sitzung</li><li>Nach der körperlichen Betätigung</li></ul><h3 id="die-schießleiter" tabindex="-1">Die Schießleiter <a class="header-anchor" href="#die-schießleiter" aria-label="Permalink to &quot;Die Schießleiter&quot;">​</a></h3><p>Eine klassische Druckübung:</p><ol><li>Beginnen Sie bei 6 Metern.</li><li>Ziel getroffen = einen Meter zurückgehen</li><li>Fehlschlag = einen Meter vorwärts (oder von vorne beginnen)</li><li>Ziel: 10 Meter erreichen</li></ol><p>Dadurch entsteht im Verlauf des Prozesses ein natürlicher Druck.</p><h2 id="mentale-trainingseinheiten" tabindex="-1">Mentale Trainingseinheiten <a class="header-anchor" href="#mentale-trainingseinheiten" aria-label="Permalink to &quot;Mentale Trainingseinheiten&quot;">​</a></h2><p>Widmen Sie sich gezielt Zeit für mentale Fähigkeiten:</p><h3 id="visualisierungssitzung-15-20-min" tabindex="-1">Visualisierungssitzung (15-20 Min.) <a class="header-anchor" href="#visualisierungssitzung-15-20-min" aria-label="Permalink to &quot;Visualisierungssitzung (15-20 Min.)&quot;">​</a></h3><ol><li>Suche dir einen ruhigen Ort</li><li>Schließe deine Augen</li><li>Stell dir vor, du nimmst an einem Wettbewerb teil.</li><li>Erfolgreiche Würfe im Detail ansehen</li><li>Spüre das Selbstvertrauen und den Flow.</li><li>Üben Sie den Umgang mit Drucksituationen</li></ol><h3 id="routineubungen-vor-dem-schuss" tabindex="-1">Routineübungen vor dem Schuss <a class="header-anchor" href="#routineubungen-vor-dem-schuss" aria-label="Permalink to &quot;Routineübungen vor dem Schuss&quot;">​</a></h3><ul><li>Übe deine Routine, ohne zu werfen.</li><li>Konzentriere dich auf die mentalen Übergänge</li><li>Gewöhnen Sie sich die Gewohnheit der konsequenten Vorbereitung an.</li></ul><h3 id="genesungspraxis" tabindex="-1">Genesungspraxis <a class="header-anchor" href="#genesungspraxis" aria-label="Permalink to &quot;Genesungspraxis&quot;">​</a></h3><ul><li>absichtlich Fehler in der Praxis machen</li><li>Üben Sie Ihre SOAS-Antwort</li><li>Entwickeln Sie die Gewohnheit, Ihren Geist schnell wieder ins Gleichgewicht zu bringen.</li></ul><h2 id="strukturierung-deiner-trainingswoche" tabindex="-1">Strukturierung deiner Trainingswoche <a class="header-anchor" href="#strukturierung-deiner-trainingswoche" aria-label="Permalink to &quot;Strukturierung deiner Trainingswoche&quot;">​</a></h2><h3 id="beispiel-ambitionierter-amateur-6-stunden-woche" tabindex="-1">Beispiel: Ambitionierter Amateur (6 Stunden/Woche) <a class="header-anchor" href="#beispiel-ambitionierter-amateur-6-stunden-woche" aria-label="Permalink to &quot;Beispiel: Ambitionierter Amateur (6 Stunden/Woche)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tag</th><th>Dauer</th><th>Fokus</th></tr></thead><tbody><tr><td>Montag</td><td>1,5 Std.</td><td>Technik: Spitzübungen</td></tr><tr><td>Mittwoch</td><td>1,5 Std.</td><td>Technik: Schießübungen</td></tr><tr><td>Freitag</td><td>1 Stunde</td><td>Mental: Visualisierung, regelmäßiges Üben</td></tr><tr><td>Samstag</td><td>2 Std.</td><td>Spielgeschehen mit Druckelementen</td></tr></tbody></table><h3 id="beispiel-wettkampfspieler-10-stunden-woche" tabindex="-1">Beispiel: Wettkampfspieler (10 Stunden/Woche) <a class="header-anchor" href="#beispiel-wettkampfspieler-10-stunden-woche" aria-label="Permalink to &quot;Beispiel: Wettkampfspieler (10 Stunden/Woche)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tag</th><th>Dauer</th><th>Fokus</th></tr></thead><tbody><tr><td>Montag</td><td>2 Std.</td><td>Technisch: Zeigen (blockiert → zufällig)</td></tr><tr><td>Dienstag</td><td>1 Stunde</td><td>Mentales Training + Visualisierung</td></tr><tr><td>Mittwoch</td><td>2 Std.</td><td>Technik: Schuss (blockiert → zufällig)</td></tr><tr><td>Donnerstag</td><td>1 Stunde</td><td>Videorezension + geistige Arbeit</td></tr><tr><td>Freitag</td><td>2 Std.</td><td>Drucksimulation, Spielszenarien</td></tr><tr><td>Samstag</td><td>2 Std.</td><td>Wettkampf oder Spiel</td></tr></tbody></table><h2 id="trainingsprinzipien" tabindex="-1">Trainingsprinzipien <a class="header-anchor" href="#trainingsprinzipien" aria-label="Permalink to &quot;Trainingsprinzipien&quot;">​</a></h2><h3 id="_1-qualitat-vor-quantitat" tabindex="-1">1. Qualität vor Quantität <a class="header-anchor" href="#_1-qualitat-vor-quantitat" aria-label="Permalink to &quot;1. Qualität vor Quantität&quot;">​</a></h3><ul><li>30 konzentrierte Minuten sind besser als 2 Stunden sinnloses Wiederholen.</li><li>Stoppen, sobald die Konzentration nachlässt</li><li>Besser frühzeitig aufhören, als schlechte Gewohnheiten zu pflegen.</li></ul><h3 id="_2-bewusstes-uben" tabindex="-1">2. Bewusstes Üben <a class="header-anchor" href="#_2-bewusstes-uben" aria-label="Permalink to &quot;2. Bewusstes Üben&quot;">​</a></h3><ul><li>Setzen Sie sich für jede Trainingseinheit ein konkretes Ziel.</li><li>Arbeite am Rande deiner Fähigkeiten</li><li>Feedback einholen (Video, Partner, Ergebnisse)</li><li>Passen Sie Ihre Einstellungen an die Erkenntnisse an, die Sie gewonnen haben.</li></ul><h3 id="_3-genesung-ist-wichtig" tabindex="-1">3. Genesung ist wichtig <a class="header-anchor" href="#_3-genesung-ist-wichtig" aria-label="Permalink to &quot;3. Genesung ist wichtig&quot;">​</a></h3><ul><li>Ruhetage sind Teil des Trainings</li><li>Schlaf beeinflusst die Leistungsfähigkeit erheblich.</li><li>Mentale Erschöpfung ist real – respektiere sie.</li></ul><h3 id="_4-alles-dokumentieren" tabindex="-1">4. Alles dokumentieren <a class="header-anchor" href="#_4-alles-dokumentieren" aria-label="Permalink to &quot;4. Alles dokumentieren&quot;">​</a></h3><ul><li>Führe ein Trainingsprotokoll</li><li>Notieren Sie, was funktioniert und was nicht.</li><li>Regelmäßig überprüfen</li><li>Passen Sie Ihren Tarif anhand der Daten an.</li></ul><h2 id="in-diesem-abschnitt" tabindex="-1">In diesem Abschnitt <a class="header-anchor" href="#in-diesem-abschnitt" aria-label="Permalink to &quot;In diesem Abschnitt&quot;">​</a></h2><ul><li><strong><a href="/en/education/training/drills">Trainingsübungen</a></strong> - Spezielle Übungen für verschiedene Fertigkeiten</li></ul><h2 id="wichtigste-erkenntnis" tabindex="-1">Wichtigste Erkenntnis <a class="header-anchor" href="#wichtigste-erkenntnis" aria-label="Permalink to &quot;Wichtigste Erkenntnis&quot;">​</a></h2><blockquote><p>Wie du trainierst, bestimmt deine Leistung. Trainiere so, wie du spielen willst.</p></blockquote><p>Gestalte dein Training abwechslungsreich. Integriere mentale Übungen. Setze dich unter Druck. Verfolge deine Fortschritte.</p>',55))])}]]);export{o as __pageData,g as default};
